#!/usr/bin/env python3
from pathlib import Path
import base64
import subprocess
import sys
import zlib
sys.dont_write_bytecode = True
ROOT = Path(__file__).resolve().parents[1]
R = ROOT/'Source/AERISFlightControl/Terrain/AERISTerrainGpuTileRenderer.cs'
M = ROOT/'Source/AERISFlightControl/Performance/AERISOperationHealthPenicillin.cs'
C = ROOT/'GameData/AERISFlightControl/Config/AERISOperationHealth.cfg'
U = ROOT/'build_ubuntu.sh'
PATCH_B64 = ''
PREFIX='[AERIS25 DIAZEPAM PHASE7_001 REV006]'
MARKER='AERIS25_PHASE7_001_DIAZEPAM_RESIDENT_RAM_REUSE'

def text(path): return path.read_text()

def is_rev006():
    try:
        return (MARKER in text(R) and
            'internal const string Codename = "DIAZEPAM";' in text(M) and
            'internal const string Revision = "OH_PHASE7_001";' in text(M) and
            'internal const string Candidate = "AERIS25_RESIDENT_RAM_REUSE_STRENGTHENING";' in text(M) and
            'codename = DIAZEPAM' in text(C) and
            'DIAZEPAM RESIDENT RAM REUSE STRENGTHENING REV006' in text(U))
    except OSError:
        return False

if is_rev006():
    print(PREFIX+' patch already present')
    raise SystemExit(0)

try:
    r,m,c,u=text(R),text(M),text(C),text(U)
except OSError as exc:
    raise SystemExit(PREFIX+' required file missing: '+str(exc))
if not ('AERIS25_PHASE6_003_AUTHORITATIVE_PUBLICATION' in r and
        'AERIS25_PHASE6_004_MANAGED_PREPARATION_PIPELINE' not in r and
        'internal const string Codename = "NOREPINEPHRINE";' in m and
        'internal const string Revision = "OH_PHASE6_003";' in m and
        'internal const string Candidate = "AERIS25_MAIN_THREAD_COMMIT_GOVERNOR";' in m and
        'codename = NOREPINEPHRINE' in c and
        'REV003 AUTHORITATIVE PUBLICATION' in u):
    raise SystemExit(PREFIX+' exact frozen REV003 parent identity required')
patch = zlib.decompress(base64.b64decode(PATCH_B64))
subprocess.run(['git','-C',str(ROOT),'apply','--check','-'],input=patch,check=True)
subprocess.run(['git','-C',str(ROOT),'apply','--whitespace=nowarn','-'],input=patch,check=True)
if not is_rev006():
    raise SystemExit(PREFIX+' post-apply identity verification failed')
print(PREFIX+' patch applied')
print('Invariant: no new worker dependency; prepared CPU presentation is retained under the existing render-ready RAM lifetime/budget.')
